            ContentManifest = _ContentManifest,
            Scopes = _Scopes,
            Counters = _Counters,
        };
    }

    /// <inheritdoc/>
    public bool Equals(Stats? other)
    {
        if (other is null)
        {
            return false;
        }

        return Frame == other.Frame
            && SimTick == other.SimTick
            && TicksThisFrame == other.TicksThisFrame
            && WireEquality.Float(Alpha, other.Alpha)
            && FrameTimeNs == other.FrameTimeNs
            && WireEquality.Float(Fps, other.Fps)
            && DroppedTimeNs == other.DroppedTimeNs
            && ContentSwaps == other.ContentSwaps
            && ContentManifest == other.ContentManifest
            && WireEquality.Lists(Scopes, other.Scopes)
            && WireEquality.Lists(Counters, other.Counters);
    }

    /// <inheritdoc/>
    public override bool Equals(object? obj) => Equals(obj as Stats);

    /// <inheritdoc/>
    public override int GetHashCode()
    {
        var hash = new HashCode();
        hash.Add(Frame);
        hash.Add(SimTick);
        hash.Add(TicksThisFrame);
        hash.Add(BitConverter.SingleToInt32Bits(Alpha));
        hash.Add(FrameTimeNs);
        hash.Add(BitConverter.SingleToInt32Bits(Fps));
        hash.Add(DroppedTimeNs);
        hash.Add(ContentSwaps);
        hash.Add(ContentManifest);
        hash.Add(Scopes?.Count ?? -1);
        hash.Add(Counters?.Count ?? -1);
        return hash.ToHashCode();
    }
}

/// <summary>
/// Requests a hot-swap of one Sigil unit (contract §13, message id <c>0x0020</c>, <c>T→E</c>).
/// </summary>
public sealed class SwapSigilUnit : IEquatable<SwapSigilUnit>
{
    /// <summary>
    /// <c>AssetPath</c> of the unit to swap in.
    /// </summary>
    public string UnitPath { get; set; } = string.Empty;

    /// <summary>
    /// Binary <c>SigilUnit</c> bytes (contract §11.1); at most <c>MAX_UNIT_BYTES</c>.
    /// </summary>
