/// <summary>
/// Acknowledges a <c>SwapSigilUnit</c> request (contract §13, message id <c>0x0021</c>, <c>E→T</c>).
/// <c>#[non_exhaustive]</c> with <c>Default</c>: the facade builds it outside <c>grimoire_debug</c>
/// (contract §2 rule 13).
/// </summary>
public sealed class SwapAck : IEquatable<SwapAck>
{
    /// <summary>
    /// <c>seq</c> of the triggering <c>SwapSigilUnit</c> frame.
    /// </summary>
    public uint InReplyTo { get; set; }

    /// <summary>
    /// <c>0</c> applied, <c>1</c> rejected, <c>2</c> superseded by a later swap of the same unit.
    /// </summary>
    public byte Status { get; set; }

    /// <summary>
    /// First tick that ran with the new unit; <c>0</c> if not applied.
    /// </summary>
    public ulong AppliedTick { get; set; }

    /// <summary>
    /// Number of Sigil unit swaps applied so far (after this one, if applied).
    /// </summary>
    public uint ContentSwaps { get; set; }

    /// <summary>
    /// Content epoch after this swap (contract §11.8).
    /// </summary>
    public ulong ContentManifest { get; set; }

    /// <summary>
    /// The swapped unit's <c>SigilUnit::content_hash</c>.
    /// </summary>
    public ulong UnitHash { get; set; }

    /// <summary>
    /// Human-readable detail when <c>status != 0</c>.
    /// </summary>
    public string Reason { get; set; } = string.Empty;

    /// <summary>
    /// Encodes this value into a new array (contract §2 rule 9).
    /// </summary>
    /// <exception cref="WireFormatException">A length or count exceeds its maximum.</exception>
    public byte[] Encode()
    {
        var writer = new WireWriter();
        EncodeTo(writer);
        return writer.ToArray();
    }

    /// <summary>
    /// Appends this value to <paramref name="writer"/> in wire order.
    /// </summary>
    /// <exception cref="WireFormatException">A length or count exceeds its maximum.</exception>
    public void EncodeTo(WireWriter writer)
    {
        ArgumentNullException.ThrowIfNull(writer);
        writer.U32(InReplyTo);
        writer.U8(Status);
        writer.U64(AppliedTick);
        writer.U32(ContentSwaps);
        writer.U64(ContentManifest);
        writer.U64(UnitHash);
        writer.StrU32("reason", 1024, Reason);
    }

    /// <summary>
    /// Decodes a value from exactly <paramref name="bytes"/>; left-over bytes are an error.
    /// </summary>
    /// <exception cref="WireFormatException">The bytes are not a valid encoding.</exception>
    public static SwapAck Decode(ReadOnlySpan<byte> bytes)
    {
        var reader = new WireReader(bytes);
        var value = DecodeFrom(ref reader);
        reader.Finish();
        return value;
    }

    /// <summary>
    /// Decodes a value from <paramref name="reader"/>, leaving any bytes after it unread.
    /// </summary>
    /// <exception cref="WireFormatException">The bytes are not a valid encoding.</exception>
    public static SwapAck DecodeFrom(ref WireReader reader)
    {
        var _InReplyTo = reader.U32();
        var _Status = reader.U8();
        var _AppliedTick = reader.U64();
        var _ContentSwaps = reader.U32();
        var _ContentManifest = reader.U64();
        var _UnitHash = reader.U64();
        var _Reason = reader.StrU32("reason", 1024);
        return new SwapAck
        {
            InReplyTo = _InReplyTo,
            Status = _Status,
            AppliedTick = _AppliedTick,
            ContentSwaps = _ContentSwaps,
            ContentManifest = _ContentManifest,
            UnitHash = _UnitHash,
            Reason = _Reason,
        };
    }

    /// <inheritdoc/>
    public bool Equals(SwapAck? other)
    {
        if (other is null)
        {
            return false;
        }

        return InReplyTo == other.InReplyTo
            && Status == other.Status
            && AppliedTick == other.AppliedTick
            && ContentSwaps == other.ContentSwaps
            && ContentManifest == other.ContentManifest
            && UnitHash == other.UnitHash
            && string.Equals(Reason, other.Reason, StringComparison.Ordinal);
    }

    /// <inheritdoc/>
    public override bool Equals(object? obj) => Equals(obj as SwapAck);

    /// <inheritdoc/>
    public override int GetHashCode()
    {
        var hash = new HashCode();
        hash.Add(InReplyTo);
        hash.Add(Status);
        hash.Add(AppliedTick);
        hash.Add(ContentSwaps);
        hash.Add(ContentManifest);
        hash.Add(UnitHash);
        hash.Add(Reason, StringComparer.Ordinal);
        return hash.ToHashCode();
    }
}

/// <summary>
/// Requests an offline preview run of a Sigil unit (contract §13, message id <c>0x0022</c>, <c>T→E</c>).
/// In protocol v1 the engine always answers <c>Error(NotSupported)</c> (the editor preview uses
/// <c>sigilc simulate</c> instead, project ADR-0010); the payload is still defined so the codec and
/// its fixtures are complete for when a later version implements it.
/// </summary>
public sealed class SigilPreview : IEquatable<SigilPreview>
{
    /// <summary>
    /// <c>AssetPath</c> of the unit to preview.
    /// </summary>
    public string UnitPath { get; set; } = string.Empty;

    /// <summary>
    /// Binary <c>SigilUnit</c> bytes; at most <c>MAX_UNIT_BYTES</c>.
    /// </summary>
    public byte[] UnitBytes { get; set; } = Array.Empty<byte>();

    /// <summary>
    /// Number of ticks to simulate.
    /// </summary>
    public uint Ticks { get; set; }

    /// <summary>
    /// Optional aim-target position sampled during the preview.
    /// </summary>
    public float[]? Target { get; set; }

    /// <summary>
    /// Encodes this value into a new array (contract §2 rule 9).
    /// </summary>
    /// <exception cref="WireFormatException">A length or count exceeds its maximum.</exception>
    public byte[] Encode()
    {
        var writer = new WireWriter();
        EncodeTo(writer);
        return writer.ToArray();
    }

    /// <summary>
    /// Appends this value to <paramref name="writer"/> in wire order.
    /// </summary>
    /// <exception cref="WireFormatException">A length or count exceeds its maximum.</exception>
    public void EncodeTo(WireWriter writer)
    {
        ArgumentNullException.ThrowIfNull(writer);
        writer.StrU32("unit_path", 255, UnitPath);
        writer.BytesU32("unit_bytes", 8388608, UnitBytes);
        writer.U32(Ticks);
        if (Target is null)
        {
            writer.OptionTag(false);
        }
        else
        {
            writer.OptionTag(true);
            writer.Floats("target", 2, Target);
        }
    }

    /// <summary>
    /// Decodes a value from exactly <paramref name="bytes"/>; left-over bytes are an error.
    /// </summary>
    /// <exception cref="WireFormatException">The bytes are not a valid encoding.</exception>
    public static SigilPreview Decode(ReadOnlySpan<byte> bytes)
    {
        var reader = new WireReader(bytes);
        var value = DecodeFrom(ref reader);
        reader.Finish();
        return value;
    }

    /// <summary>
    /// Decodes a value from <paramref name="reader"/>, leaving any bytes after it unread.
    /// </summary>
    /// <exception cref="WireFormatException">The bytes are not a valid encoding.</exception>
    public static SigilPreview DecodeFrom(ref WireReader reader)
    {
        var _UnitPath = reader.StrU32("unit_path", 255);
        var _UnitBytes = reader.BytesU32("unit_bytes", 8388608);
        var _Ticks = reader.U32();
        float[]? _Target = null;
        if (reader.OptionTag("target"))
        {
            var _TargetInner = reader.Floats(2);
            _Target = _TargetInner;
        }
        return new SigilPreview
        {
            UnitPath = _UnitPath,
            UnitBytes = _UnitBytes,
            Ticks = _Ticks,
            Target = _Target,
        };
    }

    /// <inheritdoc/>
    public bool Equals(SigilPreview? other)
    {
        if (other is null)
        {
            return false;
        }

        return string.Equals(UnitPath, other.UnitPath, StringComparison.Ordinal)
            && WireEquality.Bytes(UnitBytes, other.UnitBytes)
            && Ticks == other.Ticks
            && (Target is null ? other.Target is null : other.Target is not null && WireEquality.Floats(Target, other.Target));
    }

    /// <inheritdoc/>
    public override bool Equals(object? obj) => Equals(obj as SigilPreview);

    /// <inheritdoc/>
    public override int GetHashCode()
    {
        var hash = new HashCode();
        hash.Add(UnitPath, StringComparer.Ordinal);
        hash.Add(UnitBytes?.Length ?? -1);
        hash.Add(Ticks);
        hash.Add(Target?.Length ?? -1);
        return hash.ToHashCode();
    }
}

/// <summary>
/// Schema <c>debug_protocol_v1</c>.
/// Payload types of the Grimoire debug protocol v1 (engine contract §13).
/// </summary>
public static class DebugProtocolV1
{
    /// <summary>
    /// Format or protocol version the schema describes.
    /// </summary>
    public const uint FormatVersion = 1;

    /// <summary>
    /// Message id of <c>Hello</c>, direction T↔E, payload <c>Hello</c>.
    /// Handshake request/response.
    /// </summary>
    public const ushort HelloId = 0x0001;

    /// <summary>
    /// Message id of <c>Error</c>, direction T↔E, payload <c>ErrorMsg</c>.
    /// Protocol- or application-level error.
    /// </summary>
    public const ushort ErrorId = 0x0002;

    /// <summary>
    /// Message id of <c>Log</c>, direction E→T, payload <c>LogMsg</c>.
    /// One forwarded engine log line.
    /// </summary>
    public const ushort LogId = 0x0003;

    /// <summary>
    /// Message id of <c>Stats</c>, direction E→T, payload <c>Stats</c>.
    /// Per-frame profiler snapshot.
    /// </summary>
    public const ushort StatsId = 0x0010;

    /// <summary>
    /// Message id of <c>SwapSigilUnit</c>, direction T→E, payload <c>SwapSigilUnit</c>.
    /// Hot-swap request.
    /// </summary>
    public const ushort SwapSigilUnitId = 0x0020;

    /// <summary>
    /// Message id of <c>SwapAck</c>, direction E→T, payload <c>SwapAck</c>.
    /// Hot-swap acknowledgement.
    /// </summary>
    public const ushort SwapAckId = 0x0021;

    /// <summary>
    /// Message id of <c>SigilPreview</c>, direction T→E, payload <c>SigilPreview</c>.
    /// Offline preview request (<c>NotSupported</c> in v1).
    /// </summary>
    public const ushort SigilPreviewId = 0x0022;

    /// <summary>
    /// The message catalogue in id order of declaration.
    /// </summary>
    public static IReadOnlyList<MessageCatalogueEntry> Catalogue { get; } = new MessageCatalogueEntry[]
    {
        new(HelloId, "Hello", MessageDirection.Both, typeof(Hello)),
        new(ErrorId, "Error", MessageDirection.Both, typeof(ErrorMsg)),
        new(LogId, "Log", MessageDirection.EngineToTool, typeof(LogMsg)),
        new(StatsId, "Stats", MessageDirection.EngineToTool, typeof(Stats)),
        new(SwapSigilUnitId, "SwapSigilUnit", MessageDirection.ToolToEngine, typeof(SwapSigilUnit)),
        new(SwapAckId, "SwapAck", MessageDirection.EngineToTool, typeof(SwapAck)),
        new(SigilPreviewId, "SigilPreview", MessageDirection.ToolToEngine, typeof(SigilPreview)),
    };
}
